"""Payment domain: the gateway port the API calls."""
from dataclasses import dataclass
from typing import Protocol


class GatewayError(Exception):
    """The payment provider refused or failed; its message is the provider's own text."""


@dataclass(frozen=True)
class Charge:
    payment_id: str
    amount_cents: int


class PaymentGateway(Protocol):
    def charge(self, card_token: str, amount_cents: int) -> Charge: ...

