export type OrderStatus = "placed" | "shipped" | "cancelled";
export interface Order { readonly id: string; readonly status: OrderStatus; }
export function cancel(order: Order): Order {
  if (order.status === "shipped") throw new Error("a shipped order cannot be cancelled");
  return { ...order, status: "cancelled" };
}

